using LiBot.Application.Interfaces; using LiBot.Application.Models.BookTransaction; using LiBot.Domain.Enums; using LiBot.Domain.Inventory; using LiBot.Domain.Library; using LiBot.Infrastructure.Persistence; using Microsoft.EntityFrameworkCore;
namespace LiBot.Infrastructure.Repositories;
public sealed class BookTransactionRepository(LiBotDbContext db) : IBookTransactionRepository
{
 public Task<TransactionListResponse> ListReceiptsAsync(int p,int s,string? t,string? st,string? q,DateOnly? f,DateOnly? to,CancellationToken ct)=>ListReceiptCore(p,s,t,st,q,f,to,ct);
 public async Task<TransactionResponse?> GetReceiptAsync(Guid id,CancellationToken ct)=>await Receipt(db.BookReceipts.Where(x=>x.Id==id),ct);
 public async Task<TransactionResponse> CreateReceiptAsync(CreateBookReceiptRequest r,CancellationToken ct){if(r.Items.Count==0)throw new ArgumentException("Receipt requires items.");var h=new BookReceipt(r.ReceiptType,Enum.Parse<BookReceiptStatus>(r.Status??"DRAFT",true),r.Items.Count,r.ReceivedDate,r.Note);db.BookReceipts.Add(h);await AddReceiptDetails(h,r.Items,ct);await db.SaveChangesAsync(ct);return(await GetReceiptAsync(h.Id,ct))!;}
 public async Task<TransactionResponse> UpdateReceiptAsync(Guid id,CreateBookReceiptRequest r,CancellationToken ct){var h=await db.BookReceipts.FindAsync([id],ct)??throw new KeyNotFoundException("Receipt not found.");h.Update(r.ReceiptType,r.ReceivedDate,r.Note,r.Items.Count);var old=await db.BookReceiptDetails.Where(x=>x.ReceiptId==id).ToListAsync(ct);if(h.ReceiptType=="NEW_ACQUISITION")foreach(var d in old){var item=await db.BookItems.FindAsync([d.BookItemId],ct);if(item?.Status==BookItemStatus.PENDING_RECEIPT)db.BookItems.Remove(item);}db.BookReceiptDetails.RemoveRange(old);await AddReceiptDetails(h,r.Items,ct);if(!string.IsNullOrWhiteSpace(r.Status)&&Enum.TryParse<BookReceiptStatus>(r.Status,true,out var target)&&target!=h.Status){Check(h.Status,target);h.UpdateStatus(target);}await db.SaveChangesAsync(ct);return(await GetReceiptAsync(id,ct))!;}
 public async Task<TransactionResponse> UpdateReceiptStatusAsync(Guid id,string s,CancellationToken ct){var h=await db.BookReceipts.FindAsync([id],ct)??throw new KeyNotFoundException("Receipt not found.");var target=Enum.Parse<BookReceiptStatus>(s,true);Check(h.Status,target);var details=await db.BookReceiptDetails.Where(x=>x.ReceiptId==id).ToListAsync(ct);if(target==BookReceiptStatus.COMPLETED)foreach(var d in details){var item=await db.BookItems.FindAsync([d.BookItemId],ct)??throw new KeyNotFoundException("Book item not found.");item.Update(item.BookId,item.Barcode,item.ExpectedShelfLevelId,item.CurrentShelfLevelId,BookItemStatus.AVAILABLE);}if(target==BookReceiptStatus.CANCELLED&&h.ReceiptType.Equals("NEW_ACQUISITION",StringComparison.OrdinalIgnoreCase)){foreach(var d in details){var item=await db.BookItems.FindAsync([d.BookItemId],ct);if(item?.Status==BookItemStatus.PENDING_RECEIPT)db.BookItems.Remove(item);}db.BookReceiptDetails.RemoveRange(details);}h.UpdateStatus(target);await db.SaveChangesAsync(ct);return(await GetReceiptAsync(id,ct))!;}
 public Task<TransactionListResponse> ListIssuesAsync(int p,int s,string? t,string? st,string? q,DateOnly? f,DateOnly? to,CancellationToken ct)=>ListIssueCore(p,s,t,st,q,f,to,ct);
 public async Task<TransactionResponse?> GetIssueAsync(Guid id,CancellationToken ct)=>await Issue(db.BookIssues.Where(x=>x.Id==id),ct);
 public async Task<TransactionResponse> CreateIssueAsync(CreateBookIssueRequest r,CancellationToken ct){if(r.Items.Count==0)throw new ArgumentException("Issue requires items.");var h=new BookIssue(r.IssueType,Enum.Parse<BookIssueStatus>(r.Status??"DRAFT",true),r.Items.Count,r.IssueDate,r.Note);db.BookIssues.Add(h);foreach(var x in r.Items){var item=await db.BookItems.SingleOrDefaultAsync(i=>i.Barcode==x.Barcode,ct)??throw new KeyNotFoundException("Book item was not found.");if(item.BookId!=x.BookId)throw new ArgumentException("Book item does not match book.");if(r.IssueType.Equals("BORROW_LOAN",StringComparison.OrdinalIgnoreCase)&&item.Status!=BookItemStatus.AVAILABLE)throw new InvalidOperationException("Only AVAILABLE items can be loaned.");db.BookIssueDetails.Add(new BookIssueDetail(h.Id,item.Id,item.BookId,x.Note));}await db.SaveChangesAsync(ct);return(await GetIssueAsync(h.Id,ct))!;}
 public async Task<TransactionResponse> UpdateIssueAsync(Guid id,CreateBookIssueRequest r,CancellationToken ct){var h=await db.BookIssues.FindAsync([id],ct)??throw new KeyNotFoundException("Issue not found.");h.Update(r.IssueType,r.IssueDate,r.Note,r.Items.Count);db.BookIssueDetails.RemoveRange(await db.BookIssueDetails.Where(x=>x.IssueId==id).ToListAsync(ct));foreach(var x in r.Items){var item=await db.BookItems.SingleOrDefaultAsync(i=>i.Barcode==x.Barcode,ct)??throw new KeyNotFoundException("Book item was not found.");if(item.BookId!=x.BookId)throw new ArgumentException("Book item does not match book.");db.BookIssueDetails.Add(new BookIssueDetail(id,item.Id,item.BookId,x.Note));}if(!string.IsNullOrWhiteSpace(r.Status)&&Enum.TryParse<BookIssueStatus>(r.Status,true,out var target)&&target!=h.Status){Check(h.Status,target);h.UpdateStatus(target);}await db.SaveChangesAsync(ct);return(await GetIssueAsync(id,ct))!;}
 public async Task<TransactionResponse> UpdateIssueStatusAsync(Guid id,string s,CancellationToken ct){var h=await db.BookIssues.FindAsync([id],ct)??throw new KeyNotFoundException("Issue not found.");var target=Enum.Parse<BookIssueStatus>(s,true);Check(h.Status,target);if(target==BookIssueStatus.COMPLETED)foreach(var d in await db.BookIssueDetails.Where(x=>x.IssueId==id).ToListAsync(ct)){var i=await db.BookItems.FindAsync([d.BookItemId],ct)??throw new KeyNotFoundException("Book item not found.");i.Update(i.BookId,i.Barcode,i.ExpectedShelfLevelId,i.CurrentShelfLevelId,h.IssueType=="DISPOSAL"?BookItemStatus.DAMAGED:BookItemStatus.ON_LOAN);}h.UpdateStatus(target);await db.SaveChangesAsync(ct);return(await GetIssueAsync(id,ct))!;}
 static void Check<T>(T current,T target) where T:Enum{if(current.ToString()=="DRAFT"&&(target.ToString()=="PENDING"||target.ToString()=="CANCELLED")||current.ToString()=="PENDING"&&(target.ToString()=="APPROVED"||target.ToString()=="DRAFT"||target.ToString()=="CANCELLED")||current.ToString()=="APPROVED"&&(target.ToString()=="COMPLETED"||target.ToString()=="DRAFT"||target.ToString()=="CANCELLED"))return;throw new InvalidOperationException("Invalid transaction status transition.");}
 async Task AddReceiptDetails(BookReceipt h,IReadOnlyList<TransactionItem> items,CancellationToken ct){foreach(var x in items){if(!await db.Books.AnyAsync(b=>b.Id==x.BookId,ct))throw new KeyNotFoundException("Book was not found.");BookItem item;if(h.ReceiptType.Equals("NEW_ACQUISITION",StringComparison.OrdinalIgnoreCase)){if(x.ExpectedShelfLevelId is not Guid level||!await db.ShelfLevels.AnyAsync(l=>l.Id==level,ct))throw new ArgumentException("ExpectedShelfLevelId is required.");if(await db.BookItems.AnyAsync(i=>i.Barcode==x.Barcode,ct))throw new InvalidOperationException("Barcode already exists.");item=new BookItem(x.BookId,x.Barcode,level,level,BookItemStatus.PENDING_RECEIPT);db.BookItems.Add(item);}else{item=await db.BookItems.SingleOrDefaultAsync(i=>i.Barcode==x.Barcode,ct)??throw new KeyNotFoundException("Book item was not found.");if(item.Status!=BookItemStatus.ON_LOAN)throw new InvalidOperationException("Only ON_LOAN items can be returned.");}db.BookReceiptDetails.Add(new BookReceiptDetail(h.Id,item.Id,item.BookId,x.Note));}}
 async Task<TransactionListResponse> ListReceiptCore(int p,int s,string? t,string? st,string? q,DateOnly? f,DateOnly? to,CancellationToken ct){var x=db.BookReceipts.AsQueryable();if(t!=null)x=x.Where(i=>i.ReceiptType==t);if(st!=null&&Enum.TryParse<BookReceiptStatus>(st,true,out var z))x=x.Where(i=>i.Status==z);if(f!=null)x=x.Where(i=>i.ReceivedDate>=f);if(to!=null)x=x.Where(i=>i.ReceivedDate<=to);if(!string.IsNullOrWhiteSpace(q)){var term=q.Trim();x=x.Where(h=>h.Note!.Contains(term)||db.BookReceiptDetails.Where(d=>d.ReceiptId==h.Id).Join(db.Books,d=>d.BookId,b=>b.Id,(d,b)=>b.Title+" "+b.Isbn).Any(v=>v.Contains(term)));}var n=await x.CountAsync(ct);var items=new List<TransactionResponse>();foreach(var h in await x.OrderByDescending(i=>i.ReceivedDate).Skip((p-1)*s).Take(s).ToListAsync(ct))items.Add((await GetReceiptAsync(h.Id,ct))!);return new(items,p,s,n,(int)Math.Ceiling(n/(double)s));}
 async Task<TransactionListResponse> ListIssueCore(int p,int s,string? t,string? st,string? q,DateOnly? f,DateOnly? to,CancellationToken ct){var x=db.BookIssues.AsQueryable();if(t!=null)x=x.Where(i=>i.IssueType==t);if(st!=null&&Enum.TryParse<BookIssueStatus>(st,true,out var z))x=x.Where(i=>i.Status==z);if(f!=null)x=x.Where(i=>i.IssueDate>=f);if(to!=null)x=x.Where(i=>i.IssueDate<=to);if(!string.IsNullOrWhiteSpace(q)){var term=q.Trim();x=x.Where(h=>h.Note!.Contains(term)||db.BookIssueDetails.Where(d=>d.IssueId==h.Id).Join(db.Books,d=>d.BookId,b=>b.Id,(d,b)=>b.Title+" "+b.Isbn).Any(v=>v.Contains(term)));}var n=await x.CountAsync(ct);var items=new List<TransactionResponse>();foreach(var h in await x.OrderByDescending(i=>i.IssueDate).Skip((p-1)*s).Take(s).ToListAsync(ct))items.Add((await GetIssueAsync(h.Id,ct))!);return new(items,p,s,n,(int)Math.Ceiling(n/(double)s));}
async Task<TransactionResponse?> Receipt(IQueryable<BookReceipt> q,CancellationToken ct){var h=await q.FirstOrDefaultAsync(ct);if(h==null)return null;var d=await (from x in db.BookReceiptDetails where x.ReceiptId==h.Id join b in db.Books on x.BookId equals b.Id join i in db.BookItems on x.BookItemId equals i.Id join l in db.ShelfLevels on i.ExpectedShelfLevelId equals (Guid?)l.Id into ls from l in ls.DefaultIfEmpty() join sh in db.Shelves on l.ShelfId equals sh.Id into ss from sh in ss.DefaultIfEmpty() select new TransactionDetail(x.Id,x.BookItemId,x.BookId,i.Barcode,b.Title,b.Isbn,sh==null?null:sh.Name+" • "+l.Name,x.Note)).ToListAsync(ct);return new(h.Id,h.ReceiptType,h.ReceivedDate,h.Status.ToString(),h.Total,h.Note,d);}
async Task<TransactionResponse?> Issue(IQueryable<BookIssue> q,CancellationToken ct){var h=await q.FirstOrDefaultAsync(ct);if(h==null)return null;var d=await (from x in db.BookIssueDetails where x.IssueId==h.Id join b in db.Books on x.BookId equals b.Id join i in db.BookItems on x.BookItemId equals i.Id join l in db.ShelfLevels on i.CurrentShelfLevelId equals (Guid?)l.Id into ls from l in ls.DefaultIfEmpty() join sh in db.Shelves on l.ShelfId equals sh.Id into ss from sh in ss.DefaultIfEmpty() select new TransactionDetail(x.Id,x.BookItemId,x.BookId,i.Barcode,b.Title,b.Isbn,sh==null?null:sh.Name+" • "+l.Name,x.Note)).ToListAsync(ct);return new(h.Id,h.IssueType,h.IssueDate,h.Status.ToString(),h.Total,h.Note,d);}
}
